import { useState, useEffect } from "react";
import { Link, useNavigate } from "react-router-dom";
import {
  Box,
  Typography,
  TextField,
  Button,
  Card,
  CardContent,
  Modal,
  CircularProgress,
} from "@mui/material";
import { supabase } from "../supabaseClient";

const SignUpPage = () => {
  const [formData, setFormData] = useState({ name: "", dob: "", email: "", password: "" });
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);
  const [modalOpen, setModalOpen] = useState(false);
  const [verifyStatus, setVerifyStatus] = useState("waiting"); // "waiting" | "success" | "failed"

  const navigate = useNavigate();

  const handleSignUp = async (e) => {
    e.preventDefault();
    setError(null);

    const { name, dob, email, password } = formData;
    if (!name || !dob || !email || !password) {
      setError("All fields are required!");
      return;
    }

    setLoading(true);

    const { error: signUpError } = await supabase.auth.signUp({
      email,
      password,
      options: {
        emailRedirectTo: "http://localhost:3000/verify",
      },
    });

    setLoading(false);

    if (signUpError) {
      setError(signUpError.message);
    } else {
      setModalOpen(true);
      localStorage.setItem("signupData", JSON.stringify({ name, dob, email }));
    }
  };

  // Auto-check verification from magic link
  useEffect(() => {
    const hash = window.location.hash;
    if (hash.includes("access_token")) {
      (async () => {
        const { data: sessionData, error } = await supabase.auth.getSession(); // ✅ Correct function

        if (error || !sessionData.session) {
          setVerifyStatus("failed");
          return;
        }

        setVerifyStatus("success");

        const { data: userData } = await supabase.auth.getUser();
        const saved = JSON.parse(localStorage.getItem("signupData"));

        if (userData?.user && saved) {
          await supabase.from("users").insert({
            id: userData.user.id,
            email: userData.user.email,
            name: saved.name,
            dob: saved.dob,
          });
          localStorage.removeItem("signupData");
        }
      })();
    }
  }, []);


  return (
    <>
      <Box sx={{ width: "100vw", height: "100vh", display: "flex" }}>
        {/* Left */}
        <Box
          sx={{
            width: "50%",
            backgroundColor: "#8E2839",
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
            alignItems: "center",
            color: "white",
            padding: "40px",
          }}
        >
          <Typography variant="h4" fontWeight="bold" mb={2}>
            Welcome Back!
          </Typography>
          <Typography textAlign="center" mb={4}>
            To keep connected with us, please login.
          </Typography>
          <Link to="/signin">
            <Button
              variant="outlined"
              sx={{
                color: "white",
                borderColor: "white",
                padding: "10px 32px",
                borderRadius: "999px",
              }}
            >
              SIGN IN
            </Button>
          </Link>
        </Box>

        {/* Right */}
        <Box
          sx={{
            width: "50%",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            backgroundColor: "#FFF",
          }}
        >
          <Card sx={{ width: "90%", maxWidth: 420, padding: 3, boxShadow: 3, borderRadius: 3 }}>
            <CardContent>
              <Typography variant="h4" fontWeight="bold" color="#8E2839" mb={1}>
                Create Account
              </Typography>
              <Typography color="gray" mb={3}>
                Sign up to enjoy the features of EXAM
              </Typography>

              <form onSubmit={handleSignUp}>
                <TextField
                  fullWidth
                  label="Full Name"
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  sx={{ mb: 2 }}
                  required
                />
                <TextField
                  fullWidth
                  label="Date of Birth"
                  type="date"
                  value={formData.dob}
                  onChange={(e) => setFormData({ ...formData, dob: e.target.value })}
                  InputLabelProps={{ shrink: true }}
                  sx={{ mb: 2 }}
                  required
                />
                <TextField
                  fullWidth
                  label="Email"
                  type="email"
                  value={formData.email}
                  onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                  sx={{ mb: 2 }}
                  required
                />
                <TextField
                  fullWidth
                  label="Password"
                  type="password"
                  value={formData.password}
                  onChange={(e) => setFormData({ ...formData, password: e.target.value })}
                  sx={{ mb: 2 }}
                  required
                />
                {error && (
                  <Typography color="red" fontSize="0.875rem" mb={2}>
                    {error}
                  </Typography>
                )}
                <Button
                  type="submit"
                  fullWidth
                  disabled={loading}
                  sx={{
                    backgroundColor: loading ? "#aaa" : "#8E2839",
                    color: "white",
                    padding: "12px",
                    borderRadius: "999px",
                    fontSize: "1.125rem",
                  }}
                >
                  {loading ? "Creating..." : "Create Account"}
                </Button>
              </form>
            </CardContent>
          </Card>
        </Box>
      </Box>

      {/* ✅ Modal */}
      <Modal open={modalOpen} onClose={() => setModalOpen(false)}>
        <Box
          sx={{
            position: "absolute",
            top: "50%",
            left: "50%",
            transform: "translate(-50%, -50%)",
            bgcolor: "background.paper",
            boxShadow: 24,
            borderRadius: 2,
            p: 4,
            textAlign: "center",
          }}
        >
          {verifyStatus === "waiting" && (
            <>
              <CircularProgress />
              <Typography mt={2}>Check your email to verify your account.</Typography>
            </>
          )}
          {verifyStatus === "success" && (
            <>
              <Typography variant="h6" color="green" mb={2}>
                ✅ Email Verified!
              </Typography>
              <Button variant="contained" onClick={() => navigate("/signin")}>
                Go to Login
              </Button>
            </>
          )}
          {verifyStatus === "failed" && (
            <>
              <Typography variant="h6" color="error" mb={2}>
                ❌ Verification Failed
              </Typography>
              <Typography mb={2}>Link may be expired or already used.</Typography>
              <Button variant="outlined" onClick={() => setModalOpen(false)}>
                Close
              </Button>
            </>
          )}
        </Box>
      </Modal>
    </>
  );
};

export default SignUpPage;
